(* [comment removed for export] *)
Lemma SP_TA_ok J hb : 1 <= J -> hb < 2 ^ J ->
  0 <= hl_k_per_malloc L -> 0 <= hl_b_lin L -> 0 <= hl_b_overhead L ->
